      process.env.SIGNUP_ALLOWED_DOMAINS = "*.example.com";
      jest.isolateModules(() => {
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        expect(() => require("./config")).toThrow(/SIGNUP_ALLOWED_DOMAINS/);
      });
    });

    it("reject a value that is set but lists nothing", () => {
      expect(() => parseSignupAllowedEmails(", ,")).toThrow(
        /SIGNUP_ALLOWED_EMAILS: set but lists no addresses/,
      );
      expect(() => parseSignupAllowedDomains(" , ")).toThrow(
        /SIGNUP_ALLOWED_DOMAINS: set but lists no domains/,
      );
    });

    it("reject malformed entries at boot", () => {
      for (const bad of [
        "not-an-email",
        "@example.com",
        "a@",
        "a b@example.com",
        "a@localhost",
        "a@@example.com",
        ".a@example.com",
        "a..b@example.com",
      ]) {
        expect(() => parseSignupAllowedEmails(bad)).toThrow(
          /SIGNUP_ALLOWED_EMAILS/,
        );
      }
      for (const bad of [
        "@example.com",
        "*.example.com",
        "example",
        "https://example.com",
        "a@example.com",
      ]) {
        expect(() => parseSignupAllowedDomains(bad)).toThrow(
          /SIGNUP_ALLOWED_DOMAINS/,
        );
      }
    });
  });
});

