    const { email, password, firstName, lastName, username } = params;
    const locale = "en";
    if (username) assertValidUsername(username);
    const ledger_username =
      username ||
      (await usernameFromEmail(
        email,
        async (name) =>
          (await this.models.user.getUserByUsername(this.db, name)) !== null,
      ));
