import { ErrorCategory } from "./error-category";

/**
 * Base class for all application errors.
 *
 * Transport-agnostic: it extends the plain `Error` and imports nothing from the
 * GraphQL or HTTP layers. Business logic (services, operations, shared infra)
 * throws these from any layer; the per-transport adapters
 * (`server/graphql/format-error.ts`, `server/rest/error-middleware.ts`) translate
 * a {@link ErrorCategory} into the appropriate wire format.
 *
 * @example
 * class NotFoundError extends DomainError {
 *   constructor(resource: string, id?: string) {
 *     super(ErrorCategory.NOT_FOUND, `${resource} not found`, { resource, id });
 *   }
 * }
 */
export abstract class DomainError extends Error {
  /**
   * @param category - Semantic, transport-agnostic error category (the canonical code)
   * @param message - Human-readable error message
   * @param metadata - Additional error context for debugging and client handling
   * @param httpStatusHint - Escape hatch for genuine status passthrough (e.g. the
   *   git proxy forwarding an upstream status). Consumed by the REST adapter only;
   *   when omitted the adapter derives the status from `category`.
   */
  constructor(
    public readonly category: ErrorCategory,
    message: string,
    /**
     * Error context clients branch on. A `hint` key here is the canonical
     * place to say what to do next: transports read it verbatim (the MCP
     * envelope does), so the throw site — which knows why it refused — names
     * the remedy instead of a transport guessing from the prose (w2/013).
     */
    public readonly metadata?: Record<string, unknown>,
    public readonly httpStatusHint?: number,
  ) {
    super(message);
    this.name = this.constructor.name;
  }
}

/**
 * Thrown when a request requires authentication but none was provided or the
 * provided credentials are invalid.
 *
 * Category: UNAUTHENTICATED (HTTP 401)
 *
 * @example
 * throw new UnauthenticatedError();
 * throw new UnauthenticatedError("Invalid JWT token");
 */
export class UnauthenticatedError extends DomainError {
  constructor(message = "Authentication required") {
    super(ErrorCategory.UNAUTHENTICATED, message);
  }
}

/**
 * Thrown when an authenticated user attempts to access a resource they don't have
 * permission for.
 *
 * Category: FORBIDDEN (HTTP 403)
 *
 * @example
 * throw new ForbiddenError();
 * throw new ForbiddenError("Only ledger owner can delete", "ledger");
 */
export class ForbiddenError extends DomainError {
  constructor(message = "Access denied", resource?: string, hint?: string) {
    super(ErrorCategory.FORBIDDEN, message, {
      ...(resource !== undefined && { resource }),
      ...(hint !== undefined && { hint }),
    });
  }
}

/**
 * Thrown when a requested resource does not exist.
 *
 * Category: NOT_FOUND (HTTP 404)
 *
 * @example
 * throw new NotFoundError("Ledger");
 * throw new NotFoundError("Ledger", "abc123");
 */
export class NotFoundError extends DomainError {
  constructor(resource: string, id?: string, hint?: string) {
    const message = id
      ? `${resource} with ID '${id}' not found`
      : `${resource} not found`;
    super(ErrorCategory.NOT_FOUND, message, {
      resource,
      id,
      ...(hint !== undefined && { hint }),
    });
  }
}

/**
 * Thrown when the client provides invalid input data.
 *
 * Category: BAD_USER_INPUT (HTTP 400)
 *
 * @example
 * throw new BadUserInputError("Invalid email format");
 * throw new BadUserInputError("Name cannot be empty", "name");
 */
export class BadUserInputError extends DomainError {
  constructor(message: string, field?: string, hint?: string) {
    super(ErrorCategory.BAD_USER_INPUT, message, {
      ...(field !== undefined && { field }),
      ...(hint !== undefined && { hint }),
    });
  }
}

/**
 * Thrown when input validation fails based on business rules or schema constraints.
 *
 * Category: VALIDATION_FAILED (HTTP 400)
 *
 * @example
 * throw new ValidationError("email", "Must be a valid email address");
 */
export class ValidationError extends DomainError {
  constructor(
    field: string,
    reason: string,
    hint?: string,
    details?: Record<string, unknown>,
  ) {
    super(
      ErrorCategory.VALIDATION_FAILED,
      `Validation failed for ${field}: ${reason}`,
      {
        field,
        reason,
        ...(hint !== undefined && { hint }),
        ...details,
      },
    );
  }
}

/**
 * A write that would add bean-check errors the ledger did not have, on either
 * write path: Beancount text (`text`) or structured entries (`entries`, w0/m2).
 * Each new error is named in the reason and, for clients, in
 * `newLedgerErrors` (`message (file:line); …`), as UNBALANCED carries its
 * `residual` — so an app shows what the write would break without parsing the
 * message.
 *
 * Category: VALIDATION_FAILED (HTTP 400)
 */
export class NewLedgerErrorsError extends ValidationError {
  constructor(
    field: "text" | "entries",
    count: number,
    newLedgerErrors: string,
  ) {
    const text = field === "text";
    super(
      field,
      `${text ? "appending it" : "adding these entries"} would introduce ${count} new bean-check error${count === 1 ? "" : "s"}: ${newLedgerErrors}`,
      `The ${text ? "text is valid Beancount" : "entries are valid"} but would break the ledger — the message names each new error. Fix the ${text ? "directives" : "entries"}, or pass \`allowInvalid: true\` to record them anyway.`,
      { newLedgerErrors },
    );
  }
}

/**
 * Thrown when an operation conflicts with the current state of the resource.
 *
 * Category: CONFLICT (HTTP 409)
 *
 * @example
 * throw new ConflictError("User", "Email already exists");
 */
export class ConflictError extends DomainError {
  constructor(
    resource: string,
    reason: string,
    metadata?: Record<string, unknown>,
  ) {
    super(ErrorCategory.CONFLICT, `${resource} conflict: ${reason}`, {
      ...metadata,
      resource,
      reason,
    });
  }
}

/**
 * Thrown when a client exceeds the rate limit for a particular operation.
 *
 * Category: RATE_LIMITED (HTTP 429)
 *
 * @example
 * throw new RateLimitedError(60);
 * throw new RateLimitedError(120, "Too many login attempts");
 * throw new RateLimitedError(undefined, "Monthly quota reached", { tier });
 */
export class RateLimitedError extends DomainError {
  constructor(
    retryAfter?: number,
    message = "Too many requests. Please try again later.",
    metadata?: Record<string, unknown>,
  ) {
    super(ErrorCategory.RATE_LIMITED, message, {
      ...(retryAfter !== undefined && { retryAfter }),
      ...metadata,
    });
  }
}

/**
 * Thrown when an unexpected internal server error occurs.
 *
 * Category: INTERNAL_SERVER_ERROR (HTTP 500)
 *
 * @example
 * throw new InternalServerError();
 * throw new InternalServerError("Database connection failed");
 */
export class InternalServerError extends DomainError {
  constructor(
    message = "Internal server error",
    originalError?: Error,
    httpStatusHint?: number,
  ) {
    super(
      ErrorCategory.INTERNAL_SERVER_ERROR,
      message,
      originalError ? { originalMessage: originalError.message } : undefined,
      httpStatusHint,
    );
  }
}

/**
 * Thrown when a required external service is temporarily unavailable.
 *
 * Category: SERVICE_UNAVAILABLE (HTTP 503)
 *
 * @example
 * throw new ServiceUnavailableError("Database");
 * throw new ServiceUnavailableError("Ledger API", 30);
 */
export class ServiceUnavailableError extends DomainError {
  constructor(service: string, retryAfter?: number) {
    super(
      ErrorCategory.SERVICE_UNAVAILABLE,
      `${service} is temporarily unavailable`,
      retryAfter ? { service, retryAfter } : { service },
    );
  }
}

/**
 * Thrown when a user reaches their subscription tier's resource limits.
 *
 * Category: RESOURCE_LIMIT_REACHED (HTTP 403)
 *
 * @example
 * throw new ResourceLimitReachedError("Ledger", 5, 5);
 */
export class ResourceLimitReachedError extends DomainError {
  constructor(
    resource: string,
    limit: number,
    current: number,
    /**
     * Replaces the generic sentence when the service that refused already said
     * something better. The directive limit does: its message names deleting
     * entries as the way back under, which is what the git proxy's refusal
     * sends people here to do (ADR 0005 / w1/m17 t007). Rebuilding the text
     * from the numbers would drop that and leave upgrading as the only visible
     * option.
     */
    message?: string,
  ) {
    super(
      ErrorCategory.RESOURCE_LIMIT_REACHED,
      message ??
        `${resource} limit reached. Maximum: ${limit}, Current: ${current}. Upgrade to Premium or a higher plan to continue.`,
      { resource, limit, current },
    );
  }
}

/**
 * Thrown when an operation is not allowed due to business rules or current state.
 *
 * Category: OPERATION_NOT_ALLOWED (HTTP 403)
 *
 * @example
 * throw new OperationNotAllowedError("delete", "Cannot delete default ledger");
 */
export class OperationNotAllowedError extends DomainError {
  constructor(operation: string, reason: string, hint?: string) {
    super(
      ErrorCategory.OPERATION_NOT_ALLOWED,
      `Operation '${operation}' not allowed: ${reason}`,
      { operation, reason, ...(hint !== undefined && { hint }) },
    );
  }
}

/**
 * Thrown when a feature requires a premium subscription but user is on free tier.
 *
 * Category: PREMIUM_REQUIRED (HTTP 402)
 *
 * @example
 * throw new PremiumRequiredError();
 * throw new PremiumRequiredError("AI categorization");
 */
export class PremiumRequiredError extends DomainError {
  constructor(feature?: string, customMessage?: string) {
    const message =
      customMessage ||
      (feature
        ? `Premium subscription required to access ${feature}`
        : "Premium subscription required");
    super(
      ErrorCategory.PREMIUM_REQUIRED,
      message,
      feature ? { feature } : undefined,
    );
  }
}

/**
 * A transaction whose residual is outside the ledger's tolerance (w2/m26).
 *
 * Category: UNBALANCED (HTTP 400). The residual names the offending amounts
 * (`"5 USD"`, `"0.003 EUR, 1 JPY"`) and the hint tells the agent the two ways
 * forward — fix the postings or record the imbalance deliberately.
 *
 * @example
 * throw new UnbalancedTransactionError("entry 0: Transaction does not balance: residual 5 USD", "5 USD");
 */
export class UnbalancedTransactionError extends DomainError {
  constructor(message: string, residual: string, entry?: number) {
    super(ErrorCategory.UNBALANCED, message, {
      residual,
      ...(entry !== undefined && { entry }),
      hint: `residual ${residual}; add a posting or pass allowInvalid: true`,
    });
  }
}

/**
 * The deployment is missing configuration an operation needs (w2/m26) —
 * object storage for asset uploads, downloads, and receipt parsing when no
 * bucket or credentials are set.
 *
 * Category: CONFIGURATION_ERROR (HTTP 500). The message names the missing
 * capability; the hint names the env variables that provide it, so an agent
 * can tell the operator exactly what to set instead of pasting SDK internals.
 *
 * @example
 * throw new ConfigurationError(
 *   "Object storage is not configured on this deployment",
 *   "Set TEMP_ASSETS_AWS_S3_BUCKET, TEMP_ASSETS_AWS_S3_ACCESS_KEY_ID, and TEMP_ASSETS_AWS_S3_SECRET_ACCESS_KEY (see .env.example)",
 * );
 */
export class ConfigurationError extends DomainError {
  constructor(message: string, hint?: string) {
    super(
      ErrorCategory.CONFIGURATION_ERROR,
      message,
      hint ? { hint } : undefined,
    );
  }
}

/**
 * Transport-agnostic error categories.
 *
 * A single category is the canonical, machine-readable error code emitted by
 * every transport: it is surfaced as `extensions.code` in GraphQL responses and
 * as `error.code` in REST response bodies. Transport adapters map a category to
 * the appropriate wire representation (HTTP status, GraphQL extensions) — the
 * category itself carries no transport coupling.
 */
export enum ErrorCategory {
  /** Authentication required but not provided or invalid */
  UNAUTHENTICATED = "UNAUTHENTICATED",

  /** Authenticated but insufficient permissions */
  FORBIDDEN = "FORBIDDEN",

  /** Requested resource does not exist */
  NOT_FOUND = "NOT_FOUND",

  /** Client provided invalid input data */
  BAD_USER_INPUT = "BAD_USER_INPUT",

  /** Input validation failed against business rules or schema */
  VALIDATION_FAILED = "VALIDATION_FAILED",

  /** Operation conflicts with current resource state */
  CONFLICT = "CONFLICT",

  /** Client exceeded rate limit */
  RATE_LIMITED = "RATE_LIMITED",

  /** Unexpected internal server error */
  INTERNAL_SERVER_ERROR = "INTERNAL_SERVER_ERROR",

  /** Required external service is unavailable */
  SERVICE_UNAVAILABLE = "SERVICE_UNAVAILABLE",

  /** User reached subscription tier resource limit */
  RESOURCE_LIMIT_REACHED = "RESOURCE_LIMIT_REACHED",

  /** Operation not allowed due to business rules */
  OPERATION_NOT_ALLOWED = "OPERATION_NOT_ALLOWED",

  /** Transaction residual is outside the ledger's tolerance (w2/m26) */
  UNBALANCED = "UNBALANCED",

  /** Deployment is missing configuration this operation needs (w2/m26) */
  CONFIGURATION_ERROR = "CONFIGURATION_ERROR",

  /** Premium subscription required to access this feature */
  PREMIUM_REQUIRED = "PREMIUM_REQUIRED",
}

/**
 * Canonical HTTP status code for each error category.
 *
 * Used by the REST transport adapter to translate a thrown {@link DomainError}
 * into an HTTP response status. GraphQL ignores this (it always returns 200 with
 * the category in `extensions.code`).
 */
export const CATEGORY_HTTP_STATUS: Record<ErrorCategory, number> = {
  [ErrorCategory.UNAUTHENTICATED]: 401,
  [ErrorCategory.FORBIDDEN]: 403,
  [ErrorCategory.NOT_FOUND]: 404,
  [ErrorCategory.BAD_USER_INPUT]: 400,
  [ErrorCategory.VALIDATION_FAILED]: 400,
  [ErrorCategory.CONFLICT]: 409,
  [ErrorCategory.RATE_LIMITED]: 429,
  [ErrorCategory.INTERNAL_SERVER_ERROR]: 500,
  [ErrorCategory.SERVICE_UNAVAILABLE]: 503,
  [ErrorCategory.RESOURCE_LIMIT_REACHED]: 403,
  [ErrorCategory.OPERATION_NOT_ALLOWED]: 403,
  [ErrorCategory.PREMIUM_REQUIRED]: 402,
  [ErrorCategory.UNBALANCED]: 400,
  [ErrorCategory.CONFIGURATION_ERROR]: 500,
};

